## 🚀 **تعديل `worker.js` يدعم ألوان الماركات**

هنضيف كائن `brandColors` فيه ألوان أشهر الأيقونات، ونعدل رابط الجلب.

```javascript
export default {
  async fetch(request) {
    const url = new URL(request.url);
    const iconsParam = url.searchParams.get('i') || '';
    const theme = url.searchParams.get('theme') || 'dark';
    const perline = parseInt(url.searchParams.get('perline') || '15', 10);

    const iconNames = iconsParam.split(',').map(s => s.trim()).filter(Boolean);
    if (iconNames.length === 0) {
      return new Response('No icons specified. Use ?i=js,html,css', { status: 400 });
    }

    const bgColor = theme === 'light' ? '#ffffff' : '#1a1b27';
    const perLine = Math.min(Math.max(perline, 1), 50);
    const rows = Math.ceil(iconNames.length / perLine);
    const finalWidth = perLine * 48;
    const finalHeight = rows * 48;
    const actualWidth = Math.min(iconNames.length, perLine) * 48;

    // ألوان الماركات الشهيرة (Hex بدون #)
    const brandColors = {
      'javascript': 'F7DF1E',
      'typescript': '3178C6',
      'react': '61DAFB',
      'node.js': '339933',
      'python': '3776AB',
      'html5': 'E34F26',
      'css3': '1572B6',
      'docker': '2496ED',
      'git': 'F05032',
      'github': '181717',
      'vscode': '007ACC',
      // ضيف المزيد هنا
    };

    const svgPromises = iconNames.map(async (name, index) => {
      const row = Math.floor(index / perLine);
      const col = index % perLine;
      const translate = `translate(${col * 48}, ${row * 48})`;

      // اسم الأيقونة في Simple Icons بيستخدم "." بدل "-" في بعض الحالات
      const simpleName = name.replace(/-/g, '.').toLowerCase();
      const color = brandColors[name.toLowerCase()] || brandColors[simpleName] || 'FFFFFF';

      try {
        const res = await fetch(`https://cdn.simpleicons.org/${simpleName}/${color}`);
        if (res.ok) {
          const svg = await res.text();
          return `<g transform="${translate}">${svg}</g>`;
        }
      } catch (err) {}

      // أيقونة بديلة لو فشل الجلب
      return `<g transform="${translate}">
        <rect width="48" height="48" rx="6" fill="#ccc"/>
        <text x="24" y="28" text-anchor="middle" font-family="Arial" font-size="10" fill="#000">${name}</text>
      </g>`;
    });

    const iconsSvg = await Promise.all(svgPromises);

    const finalSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${actualWidth}" height="${finalHeight}" viewBox="0 0 ${finalWidth} ${finalHeight}">
      <rect width="100%" height="100%" fill="${bgColor}"/>
      ${iconsSvg.join('')}
    </svg>`;

    return new Response(finalSvg, {
      headers: {
        'Content-Type': 'image/svg+xml',
        'Cache-Control': 'public, max-age=86400'
      }
    });
  }
};
```

