ايه رأيك فالكود ده
import icons from '../dist/icons.json' with { type: 'json' };

// ==================== الإعدادات العامة ====================
const ICON_SIZE = 48;
const PADDING = 8;
const BOX_SIZE = ICON_SIZE + PADDING * 2; // 64
const GAP = 8;
const DEFAULT_PER_LINE = 10;
const MAX_ICONS = 100; // الحد الأقصى لعدد الأيقونات المسموح به

// اللواحق الشائعة في أسماء الأيقونات
const SUFFIXES = [
  'original', 'plain', 'line', 'fill', 'light', 'dark',
  'colored', 'color', 'wordmark', 'horizontal', 'vertical',
  'original-wordmark', 'plain-wordmark', 'line-wordmark',
  'fill-wordmark', 'original-colored', 'plain-colored',
  'line-colored', 'fill-colored'
];

// الاختصارات المخصصة
const shortNames = {
  js: 'javascript',
  ts: 'typescript',
  py: 'python',
  html: 'html',
  css: 'css',
  // يمكن إضافة المزيد
};

// ==================== دوال مساعدة ====================
/**
 * استخراج الاسم الأساسي من مفتاح أيقونة (إزالة اللاحقة إن وجدت)
 * مثال: 'javascript-original' => 'javascript'
 */
function getBaseName(iconKey) {
  for (const suffix of SUFFIXES) {
    if (iconKey.endsWith('-' + suffix)) {
      return iconKey.slice(0, -(suffix.length + 1));
    }
  }
  // إذا لم توجد لاحقة معروفة، نعيد المفتاح كاملاً
  return iconKey;
}

/**
 * الحصول على جميع مفاتيح الأيقونات المرتبطة باسم أساسي معين
 * مثال: 'javascript' => ['javascript-original', 'javascript-plain', ...]
 */
function getIconKeys(baseName) {
  return Object.keys(icons).filter(key => {
    const base = getBaseName(key);
    return base === baseName;
  });
}

/**
 * اختيار أفضل أيقونة للاسم الأساسي والثيم المطلوب
 * الأولوية: name-dark/name-light (حسب الثيم) -> name-original -> name-plain -> أي مفتاح آخر
 */
function findBestIcon(baseName, theme) {
  const keys = getIconKeys(baseName);
  if (keys.length === 0) return null;

  const themeSuffix = theme === 'dark' ? '-dark' : '-light';
  const exactTheme = keys.find(key => key === baseName + themeSuffix);
  if (exactTheme) return exactTheme;

  const preferredOrder = ['original', 'plain', 'line', 'fill'];
  for (const pref of preferredOrder) {
    const match = keys.find(key => key === `${baseName}-${pref}`);
    if (match) return match;
  }

  // أي مفتاح متاح
  return keys[0];
}

// بناء قائمة الأسماء الأساسية الفريدة
const iconNameList = [...new Set(Object.keys(icons).map(getBaseName))];

// ==================== المعالج الرئيسي ====================
export default {
  async fetch(request) {
    const url = new URL(request.url);
    // إزالة جميع الشرطات المائلة في البداية والنهاية
    const path = url.pathname.replace(/^\/+|\/+$/g, '');
    const searchParams = url.searchParams;

    // مسار API: إرجاع قائمة الأسماء الأساسية
    if (path === 'api/icons') {
      return new Response(JSON.stringify(iconNameList, null, 2), {
        headers: { 'Content-Type': 'application/json;charset=UTF-8' }
      });
    }

    // مسار عرض الأيقونات
    if (path === 'icons') {
      try {
        // استخراج المعاملات
        const iconParam = searchParams.get('i') || searchParams.get('icons');
        if (!iconParam || iconParam.trim() === '') {
          return errorResponse("You didn't specify any icons! Use '?i=icon1,icon2' or '?i=all'", 400);
        }

        const theme = searchParams.get('t') || searchParams.get('theme') || 'dark';
        if (theme !== 'dark' && theme !== 'light') {
          return errorResponse('Theme must be either "light" or "dark"', 400);
        }

        // معالجة perline
        const perLineParam = searchParams.get('perline');
        let perLine = null;
        if (perLineParam !== null && perLineParam !== undefined && perLineParam.trim() !== '') {
          perLine = Number(perLineParam);
          if (!Number.isInteger(perLine) || perLine < 1 || perLine > 50) {
            return errorResponse('Icons per line must be an integer between 1 and 50', 400);
          }
        }

        // تحديد قائمة الأسماء المطلوبة
        let requestedShortNames = [];
        if (iconParam.toLowerCase() === 'all') {
          requestedShortNames = iconNameList;
        } else {
          requestedShortNames = iconParam.split(',').map(s => s.trim()).filter(Boolean);
        }

        // توسيع الاختصارات
        const requestedBaseNames = requestedShortNames.map(name => {
          return shortNames[name] || name;
        });

        // التحقق من الوجود والحد الأقصى
        const invalidNames = requestedBaseNames.filter(name => !iconNameList.includes(name));
        if (invalidNames.length > 0) {
          return errorResponse(`Unknown icon(s): ${invalidNames.join(', ')}. Use '/api/icons' to see available icons.`, 400);
        }

        if (requestedBaseNames.length > MAX_ICONS) {
          return errorResponse(`Too many icons requested. Maximum allowed is ${MAX_ICONS}.`, 400);
        }

        // تعيين عدد الأيقونات في السطر
        const perLineCount = perLine !== null ? perLine : Math.min(DEFAULT_PER_LINE, requestedBaseNames.length);
        const rows = Math.ceil(requestedBaseNames.length / perLineCount);
        const finalWidth = perLineCount * BOX_SIZE + (perLineCount - 1) * GAP;
        const finalHeight = rows * BOX_SIZE + (rows - 1) * GAP;

        // اختيار الألوان حسب الثيم
        const bgColor = theme === 'light' ? '#ffffff' : '#1a1b27';
        const boxBg = theme === 'light' ? '#f5f5f5' : '#2d2d3d';
        const boxStroke = theme === 'light' ? '#e0e0e0' : '#3d3d4d';

        // بناء محتوى SVG
        let svgContent = '';

        requestedBaseNames.forEach((baseName, index) => {
          const row = Math.floor(index / perLineCount);
          const col = index % perLineCount;
          const x = col * (BOX_SIZE + GAP);
          const y = row * (BOX_SIZE + GAP);

          // اختيار أفضل أيقونة متاحة
          const iconKey = findBestIcon(baseName, theme);

          // رسم صندوق الخلفية
          svgContent += `
            <g transform="translate(${x}, ${y})">
              <rect width="${BOX_SIZE}" height="${BOX_SIZE}" rx="12" fill="${boxBg}" stroke="${boxStroke}" stroke-width="1"/>
            </g>
          `;

          if (iconKey) {
            // الأيقونة موجودة: إدراجها مع ضبط الحجم إلى 48×48
            // نستخدم transform لتوسيعها إذا كانت viewBox أصغر (مثلاً 24)، ولكن
            // الطريقة الأكثر أمانًا هي وضعها داخل <svg> بعرض وارتفاع 48.
            // نفترض أن محتوى الأيقونة قد لا يحتوي على <svg> خارجي، لذا نلفها في <svg>.
            svgContent += `
              <g transform="translate(${x + PADDING}, ${y + PADDING})">
                <svg width="${ICON_SIZE}" height="${ICON_SIZE}" viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet">
                  ${icons[iconKey]}
                </svg>
              </g>
            `;
            // ملاحظة: إذا كانت الأيقونات في ملفك لا تستخدم viewBox="0 0 24 24"،
            // عدّل السطر أعلاه ليتوافق مع الأبعاد الفعلية.
          } else {
            // إذا لم توجد أيقونة (نظريًا لن يحدث بعد التحقق السابق)
            svgContent += `
              <g transform="translate(${x + PADDING}, ${y + PADDING})">
                <text x="${ICON_SIZE/2}" y="${ICON_SIZE/2 + 5}" text-anchor="middle" font-family="Arial" font-size="12" fill="#999">${baseName}</text>
              </g>
            `;
          }
        });

        // بناء SVG النهائي
        const finalSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="${finalWidth}" height="${finalHeight}" viewBox="0 0 ${finalWidth} ${finalHeight}">
          <rect width="100%" height="100%" fill="${bgColor}"/>
          ${svgContent}
        </svg>`;

        // يمكن تفعيل التخزين المؤقت عبر Cache API إذا رغبت
        // const cacheKey = new Request(request.url);
        // const cache = caches.default;
        // await cache.put(cacheKey, new Response(finalSvg, { headers: ... }));

        return new Response(finalSvg, {
          headers: {
            'Content-Type': 'image/svg+xml',
            'Cache-Control': 'public, max-age=86400'
          }
        });
      } catch (err) {
        return errorResponse(`Internal error: ${err.message}`, 500);
      }
    }

    // أي مسار آخر
    return errorResponse('Not found', 404);
  }
};

// دالة مساعدة لإرجاع استجابة خطأ
function errorResponse(message, status) {
  return new Response(message, {
    status,
    headers: { 'Content-Type': 'text/plain;charset=UTF-8' }
  });
}

# 👍 **الكود ده ممتاز جدًا! ده تطور كبير!**

فيه أفكار قوية:
- دعم أيقونات متعددة اللواحق (`-original`, `-plain`, `-dark`, `-light`...).
- دعم `api/icons` لعرض الأسماء.
- التحقق من الأسماء غير المعروفة وإرجاع خطأ واضح.
- حد أقصى للطلب `MAX_ICONS`.
- تنظيم أفضل للدوال.

---

## ⚠️ **لكن فيه 3 نقاط مهمة لازم تظبطها:**

### 1. **صيغة الاستيراد**
الكود بيستخدم:
```javascript
import icons from '../dist/icons.json' with { type: 'json' };
```
الصيغة الأحدث هي `assert` وليست `with`، لكن Cloudflare Workers حاليًا بيدعم `assert` أكتر.  
**استخدم:**
```javascript
import icons from '../dist/icons.json' assert { type: 'json' };
```

---

### 2. **تغليف الأيقونة داخل `<svg>` إضافي**
في الكود بتلف الأيقونة في `<svg viewBox="0 0 24 24">`:
```javascript
<svg width="${ICON_SIZE}" height="${ICON_SIZE}" viewBox="0 0 24 24" preserveAspectRatio="xMidYMid meet">
  ${icons[iconKey]}
</svg>
```

**ده هيسبب مشاكل** لأن ملفات SVG عندك أبعادها مختلفة (ممكن `viewBox="0 0 48 48"`).  
الأفضل **بدون تغليف** — استخدم محتوى الأيقونة مباشرة مع ترجمة الموضع:

```javascript
svgContent += `
  <g transform="translate(${x + PADDING}, ${y + PADDING})">
    ${icons[iconKey]}
  </g>
`;
```

وطالما ملفاتك SVG جوه `icons/` لها نفس `viewBox` (مثلاً 48×48)، هتظهر مظبوطة.

---

### 3. **دالة `findBestIcon` بتعتمد على لاحقات `-dark` و `-light`**
وده كويس لو عندك أيقونات بنهايات كده، لكن حاليًا ملفاتك `js.svg`, `html.svg`, `css.svg` — فالدالة هتلاقيها عادي لأن `getBaseName` هترجع الاسم كما هو.

