import icons from '../dist/icons.json' assert { type: 'json' };

const ICON_SIZE = 48;
const PADDING = 8;
const BOX_SIZE = ICON_SIZE + PADDING * 2;
const GAP = 8;
const DEFAULT_PER_LINE = 10;
const MAX_ICONS = 100;

const shortNames = {
  js: 'javascript',
  ts: 'typescript',
  py: 'python',
  html: 'html',
  css: 'css',
};

