## 📌 **السبب في المشكلة السابقة:**

- الأيقونات كانت `256×256`، بينما الصندوق `64×64`.
- بدون `scale`، كانت الأيقونة تتمدد خارج الصندوق وتلخبط التخطيط.
- الآن بنحسب `scale = 48 / 256 ≈ 0.1875` فتنكمش إلى `48×48` بالظبط.

---

**جرب وقولي النتيجة!** 💪😊

هو ادالي الكود ده
import icons from '../dist/icons.json';

// ---- ثوابت التخطيط ----
const ICON_SIZE = 48;                    // حجم الأيقونة الفعلي داخل الصندوق
const PADDING = 8;                       // مسافة داخلية حول الأيقونة (8 من كل جهة)
const GAP = 8;                           // المسافة بين صندوق وصندوق
const BOX = ICON_SIZE + PADDING * 2;     // = 64 (حجم الصندوق كامل)
const RADIUS = 12;                       // زوايا دائرية للصندوق
const BG = '#1b1f23';                    // خلفية داكنة ثابتة (بدون ثيمات)

function escapeAttr(str) {
  return String(str).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

// كل أيقونة بتترسم كـ <svg> واحد متداخل (مش تغليف مزدوج)
// الـ viewBox الأصلي بتاعها + width/height=48 بيخليا تتحجم تلقائيًا وبدون تشويه
// سواء كانت 24x24 أو 256x256 أو أي مقاس تاني، عن طريق preserveAspectRatio
function renderIcon(name, x, y) {
  const icon = icons[name];
  if (!icon) return '';
  return (
    `<g>` +
    `<rect x="${x}" y="${y}" width="${BOX}" height="${BOX}" rx="${RADIUS}" fill="${BG}"/>` +
    `<svg x="${x + PADDING}" y="${y + PADDING}" width="${ICON_SIZE}" height="${ICON_SIZE}" ` +
    `viewBox="${escapeAttr(icon.viewBox)}" preserveAspectRatio="xMidYMid meet">${icon.content}</svg>` +
    `</g>`
  );
}

function buildSvg(names, perline) {
  // تجاهل أي اسم أيقونة مش موجود بدل ما يكسر التخطيط
  const valid = names.filter((n) => icons[n]);

  if (valid.length === 0) {
    return `<svg xmlns="http://www.w3.org/2000/svg" width="320" height="48">` +
      `<text x="8" y="28" font-family="monospace" font-size="13" fill="#e05252">` +
      `No valid icons found</text></svg>`;
  }

  // perline اختياري: لو مش موجود أو صفر أو سالب => الكل في سطر واحد
  const columns = perline && perline > 0 ? Math.min(perline, valid.length) : valid.length;
  const rows = Math.ceil(valid.length / columns);

  const width = columns * BOX + (columns - 1) * GAP;
  const height = rows * BOX + (rows - 1) * GAP;

  let body = '';
  valid.forEach((name, idx) => {
    const col = idx % columns;
    const row = Math.floor(idx / columns);
    const x = col * (BOX + GAP);
    const y = row * (BOX + GAP);
    body += renderIcon(name, x, y);
  });

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" ` +
    `viewBox="0 0 ${width} ${height}" fill="none">${body}</svg>`
  );
}

export default {
  async fetch(request) {
    const url = new URL(request.url);

    if (url.pathname !== '/icons') {
      return new Response('Not found', { status: 404 });
    }

    const iParam = url.searchParams.get('i') || '';
    const names = iParam
      .split(',')
      .map((s) => s.trim().toLowerCase())
      .filter(Boolean);

    if (names.length === 0) {
      return new Response('Missing "i" query parameter, e.g. ?i=js,html,css', {
        status: 400,
      });
    }

    const perlineParam = url.searchParams.get('perline');
    const perline = perlineParam ? parseInt(perlineParam, 10) : 0; // 0 => سطر واحد

    const svg = buildSvg(names, perline);

    return new Response(svg, {
      headers: {
        'Content-Type': 'image/svg+xml; charset=utf-8',
        'Cache-Control': 'public, max-age=86400, immutable',
        'Access-Control-Allow-Origin': '*',
      },
    });
  },
};

السياق: يبدو أن المستخدم حصل على كود من Claude، والآن يريد تقييمه أو ربما مقارنته بما لدينا. الكود المعروض من Claude مختلف عن كودنا: يستخدم `import icons from '../dist/icons.json'` بدون تأكيد json، ويفترض أن عناصر `icons` هي كائنات لها `viewBox` و `content` بدلاً من SVG خام كنص. هذا قد لا يتوافق مع ملف JSON الذي ننتجه. الكود أيضاً بسيط وقد يكون أنظف، لكنه يعتمد على هيكلة مختلفة.

علينا توضيح: هذا الكود جيد من حيث العرض والتوسيط، لكنه يحتاج تعديل ليتوافق مع طبيعة icons.json لدينا. حالياً، `build-icons.js` يكتب قيمة كل مفتاح كنص SVG خام. أما كود Claude فيتوقع كائناً `{ viewBox, content }`. لذلك إما نعدل build-icons.js لتحويل كل SVG إلى كائن يحتوي على viewBox و content، أو نعدل worker.js ليستخدم النص الخام ونسحب viewBox بنفسنا.

الملاحظ أن الكود المعروض من Claude لا يدعم `findBestIcon` ولا `shortNames`، لكن يمكن إضافتها لاحقاً.

نظراً لأن المستخدم يطلب المساعدة، يجب أن نقدم تقييم صادق: الكود جيد، لكن يجب ملاءمته لمشروعك. ونقدم نسخة معدلة تجمع بين البساطة ومقاومة الأخطاء، مع دعم shortNames إن أمكن.

المهم: يجب أن نرد بتقييم واضح ونعطي كود معدل جاهز. المستخدم في مرحلة متقدمة، يريد حل عرض مثالي.

لنكتب رداً يشرح ملاحظاتنا على كود Claude، ثم نعطي كود `worker.js` معدلاً يتناسب مع بنية icons.json الحالية (نص SVG خام) ويفحص viewBox. يمكننا أيضاً تعديل `build-icons.js` ليجعل كل أيقونة كائن `{viewBox, content}` بدلاً من نص خام. هذا سيكون أفضل: بهذه الطريقة نستفيد من كود Claude كما هو تقريباً.

فكرة جيدة: تعديل build-icons.js ليقوم باستخراج viewBox من كل ملف SVG وتخزينه ككائن `{content, viewBox}`. ثم worker.js يستخدم `icons[name].content` و`icons[name].viewBox`. لكن قد يكون التعديل ثقيل؟ لا بأس.

نقترح تعديل بسيط لـ build-icons.js:

```js
for (const file of files) {
  if (file.endsWith('.svg')) {
    const name = file.replace('.svg', '').toLowerCase();
    const content = String(fs.readFileSync(path.join(iconsDir, file)));
    const match = content.match(/viewBox="([^"]+)"/);
    const viewBox = match ? match[1] : '0 0 24 24';
    icons[name] = { content, viewBox };
  }
}
```

ونكتب worker.js بنفس منطق كود Claude مع دعم اختياري لاختصارات بسيطة (ممكن نضيف لاحقاً). هذا سيكون نظيفاً.

نعرض كود build-icons.js معدل وكود worker.js معدل.

يجب التنبيه على أن كود Claude يستخدم `url.pathname !== '/icons'`، أي لا يدعم `/api/icons`، يمكن إضافته لاحقاً. كما لا يدعم `?i=all`، اختياري.

