## ✅ **الحل: نعدّل `build-icons.js` عشان يخزن بالشكل المطلوب، ونستخدم كود Claude مع إضافات خفيفة**

### 1️⃣ **عدّل `build-icons.js` ليكون:**

```javascript
const fs = require('fs');
const path = require('path');

const iconsDir = path.join(__dirname, 'icons');
const distDir = path.join(__dirname, 'dist');

if (!fs.existsSync(distDir)) {
  fs.mkdirSync(distDir);
}

const icons = {};
const files = fs.readdirSync(iconsDir);

for (const file of files) {
  if (file.endsWith('.svg')) {
    const name = file.replace('.svg', '').toLowerCase();
    const content = String(fs.readFileSync(path.join(iconsDir, file)));

    // استخراج viewBox من محتوى SVG
    const viewBoxMatch = content.match(/viewBox=["']([^"']+)["']/);
    const viewBox = viewBoxMatch ? viewBoxMatch[1] : '0 0 48 48';

    // تخزين كائن { content, viewBox }
    icons[name] = { content, viewBox };
  }
}

fs.writeFileSync(path.join(distDir, 'icons.json'), JSON.stringify(icons));
console.log(`✅ Generated ${Object.keys(icons).length} icons with viewBox`);
```

