const fs = require('fs');
const path = require('path');

const ICONS_DIR = path.join(__dirname, 'icons');
const OUT_DIR = path.join(__dirname, 'dist');
const OUT_FILE = path.join(OUT_DIR, 'icons.json');

function extractDim(svgContent, attr) {
  const m = svgContent.match(new RegExp(`${attr}=["']([0-9.]+)(?:px)?["']`, 'i'));
  return m ? parseFloat(m[1]) : null;
}

function extractViewBox(svgContent) {
  const vbMatch = svgContent.match(/viewBox=["']([^"']+)["']/i);
  if (vbMatch) return vbMatch[1].trim();

  // مفيش viewBox؟ نبنيه من width/height لو موجودين، وإلا افتراضي 24x24
  const w = extractDim(svgContent, 'width') || 24;
  const h = extractDim(svgContent, 'height') || 24;
  return `0 0 ${w} ${h}`;
}

function extractInner(svgContent) {
  const openTagEnd = svgContent.indexOf('>');
  const closeTagStart = svgContent.lastIndexOf('</svg>');
  if (openTagEnd === -1 || closeTagStart === -1) return '';
  return svgContent.slice(openTagEnd + 1, closeTagStart).trim();
}

function build() {
  if (!fs.existsSync(ICONS_DIR)) {
    console.error(`❌ icons/ folder not found at ${ICONS_DIR}`);
    process.exit(1);
  }

  const files = fs.readdirSync(ICONS_DIR).filter((f) => f.toLowerCase().endsWith('.svg'));
  const icons = {};
  let skipped = 0;

  for (const file of files) {
    const name = path.basename(file, '.svg').toLowerCase();
    const raw = fs.readFileSync(path.join(ICONS_DIR, file), 'utf8');

    const viewBox = extractViewBox(raw);
    const content = extractInner(raw);

    if (!content) {
      console.warn(`⚠️  تجاهلت "${file}": مش قادر أفصل محتوى الـ SVG منها.`);
      skipped++;
      continue;
    }

    icons[name] = { viewBox, content };
  }

  fs.mkdirSync(OUT_DIR, { recursive: true });
  fs.writeFileSync(OUT_FILE, JSON.stringify(icons));

  console.log(`✅ اتبنى ${Object.keys(icons).length} أيقونة -> ${OUT_FILE}`);
  if (skipped) console.log(`   (${skipped} ملف اتجاهل، راجع التحذيرات فوق)`);
}

build();



