function cleanSvg(raw) {
  return raw
    .replace(/<\?xml[^>]*\?>/gi, '')          // إزالة تعليمات XML
    .replace(/<!--[\s\S]*?-->/g, '')           // إزالة التعليقات
    .replace(/\s+/g, ' ')                      // توحيد كل المسافات لمسافة واحدة
    .replace(/>\s+</g, '><')                  // إزالة المسافات بين الوسوم
    .replace(/"/g, '"')                       // تنظيف علامات الاقتباس
    .trim();
}

function extractViewBox(raw) {
  const m = raw.match(/viewBox=["']([^"']+)["']/i);
