  const viewBoxMatch = raw.match(/viewBox=["']([^"']+)["']/i);
  const viewBox = viewBoxMatch ? viewBoxMatch[1] : '0 0 24 24';

  // استخراج المحتوى الداخلي
  const openTagEnd = raw.indexOf('>');
  const closeTagStart = raw.lastIndexOf('</svg>');
  const content = raw.slice(openTagEnd + 1, closeTagStart).trim();

  icons[name] = { viewBox, content };
}

