### 2️⃣ **ملف `src/worker.js` الجديد (نسخة مبسطة):**

```javascript
import icons from '../dist/icons.json' assert { type: 'json' };

const ICON_SIZE = 48;
const PADDING = 8;
const GAP = 8;
const BOX = ICON_SIZE + PADDING * 2;
const RADIUS = 12;
const BG = '#1a1b2e';

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const path = url.pathname.replace(/^\/+|\/+$/g, '');

    if (path === 'api/icons') {
      const names = Object.keys(icons);
      return new Response(JSON.stringify(names), {
        headers: { 'Content-Type': 'application/json;charset=UTF-8' }
      });
    }

    if (path === 'icons') {
      const iconParam = url.searchParams.get('i') || '';
      const names = iconParam.split(',').map(s => s.trim()).filter(Boolean);

      if (names.length === 0) {
        return new Response('Missing i parameter', { status: 400 });
      }

      const perline = parseInt(url.searchParams.get('perline') || '0') || 0;
      const columns = perline > 0 ? Math.min(perline, names.length) : names.length;
      const rows = Math.ceil(names.length / columns);
      const width = columns * BOX + (columns - 1) * GAP;
      const height = rows * BOX + (rows - 1) * GAP;

      let body = '';

      names.forEach((name, index) => {
        const col = index % columns;
        const row = Math.floor(index / columns);
        const x = col * (BOX + GAP);
        const y = row * (BOX + GAP);

        if (icons[name]) {
          body += `
            <g transform="translate(${x}, ${y})">
              <rect width="${BOX}" height="${BOX}" rx="${RADIUS}" fill="${BG}"/>
              <svg x="${PADDING}" y="${PADDING}" width="${ICON_SIZE}" height="${ICON_SIZE}" viewBox="${icons[name].viewBox}" preserveAspectRatio="xMidYMid meet">
                ${icons[name].content}
              </svg>
            </g>
          `;
        } else {
          body += `
            <g transform="translate(${x}, ${y})">
              <rect width="${BOX}" height="${BOX}" rx="${RADIUS}" fill="${BG}"/>
              <text x="${BOX/2}" y="${BOX/2 + 5}" text-anchor="middle" fill="#999" font-size="12">${name}</text>
            </g>
          `;
        }
      });

      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${body}</svg>`;

      return new Response(svg, {
        headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'no-cache' }
      });
    }

    return new Response('Not found', { status: 404 });
  }
};
```

