## 📄 **الكود المعدل لـ `build-icons.js` (أضفنا استخراج `fill`)**

```javascript
const fs = require('fs');
const path = require('path');

const iconsDir = path.join(__dirname, 'icons');
const distDir = path.join(__dirname, 'dist');

if (!fs.existsSync(distDir)) fs.mkdirSync(distDir);

function cleanSvg(raw) {
  return raw
    .replace(/<\?xml[^>]*\?>/gi, '')
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/\r?\n|\r/g, ' ')
    .replace(/\s+/g, ' ')
    .replace(/>\s+</g, '><')
    .trim();
}

function extractViewBox(raw) {
  const m = raw.match(/viewBox=["']([^"']+)["']/i);
  if (m) return m[1].trim();
  const w = raw.match(/\swidth=["']([0-9.]+)(?:px)?["']/i);
  const h = raw.match(/\sheight=["']([0-9.]+)(?:px)?["']/i);
  return `0 0 ${w ? w[1] : 24} ${h ? h[1] : 24}`;
}

// استخراج خصائص مهمة من وسم <svg> مثل fill, stroke, fill-opacity
function extractRootAttributes(raw) {
  const svgStart = raw.indexOf('<svg');
  if (svgStart === -1) return {};
  const openTagEnd = raw.indexOf('>', svgStart);
  if (openTagEnd === -1) return {};

  const tagContent = raw.slice(svgStart + 4, openTagEnd); // بعد '<svg'
  const attrs = {};
  const attrRegex = /([a-zA-Z-]+)=["']([^"']*)["']/g;
  let match;
  while ((match = attrRegex.exec(tagContent)) !== null) {
    const name = match[1];
    const value = match[2];
    // نأخذ فقط الخصائص التي تؤثر على العرض ولا تتعارض مع wrapper
    if (['fill', 'fill-opacity', 'stroke', 'stroke-width', 'opacity'].includes(name)) {
      attrs[name] = value;
    }
  }
  return attrs;
}

function extractInner(raw) {
  const svgStart = raw.indexOf('<svg');
  if (svgStart === -1) return null;
  const openTagEnd = raw.indexOf('>', svgStart);
  const closeTagStart = raw.lastIndexOf('</svg>');
  if (openTagEnd === -1 || closeTagStart === -1) return null;
  return raw.slice(openTagEnd + 1, closeTagStart).trim();
}

const icons = {};
const files = fs.readdirSync(iconsDir);
let skipped = 0;

for (const file of files) {
  if (!file.endsWith('.svg')) continue;

  const name = file.replace('.svg', '').toLowerCase();
  const raw = fs.readFileSync(path.join(iconsDir, file), 'utf8');

  const cleaned = cleanSvg(raw);
  const viewBox = extractViewBox(cleaned);
  const content = extractInner(cleaned);
  const rootAttrs = extractRootAttributes(cleaned);

  if (!content) {
    console.warn(`⚠️  تجاهلت "${file}": مش قادر أفصل محتوى الـ SVG.`);
    skipped++;
    continue;
  }

  icons[name] = { viewBox, content, ...rootAttrs };
}

fs.writeFileSync(path.join(distDir, 'icons.json'), JSON.stringify(icons));

console.log(`✅ Generated ${Object.keys(icons).length} icons`);
if (skipped) console.log(`   (تجاهلت ${skipped} ملف — راجع التحذيرات فوق)`);
```

