## 📄 **الكود المحدث لـ `fetch-icons.js`**

```javascript
const fs = require('fs');
const path = require('path');

const LIST_FILE = path.join(__dirname, 'icon-list.txt');
const OUTPUT_DIR = path.join(__dirname, 'icons');

// Import all icons from simple-icons with their metadata (including brand color)
const simpleIcons = require('simple-icons');

/**
 * Build a colored SVG from Simple Icons metadata.
 * Simple Icons SVGs are monochrome by design — the brand color lives in
 * the metadata `hex` field. This function rebuilds the SVG with that color
 * applied to the path, so the icon renders in its official brand color.
 */
function buildColoredSvg(icon) {
  const color = `#${icon.hex}`;
  return (
    `<svg role="img" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">` +
    `<title>${icon.title}</title>` +
    `<path fill="${color}" d="${icon.path}"/>` +
    `</svg>`
  );
}

/**
 * Find an icon object by its slug in the simple-icons exports.
 */
function findIconBySlug(slug) {
  for (const key of Object.keys(simpleIcons)) {
    const icon = simpleIcons[key];
    if (icon && icon.slug === slug) {
      return icon;
    }
  }
  return null;
}

/**
 * Normalize an icon name to a safe lowercase id.
 */
function normalizeName(name) {
  return name.trim().toLowerCase().replace(/\s+/g, '-');
}

/**
 * Main function.
 */
function main() {
  if (!fs.existsSync(LIST_FILE)) {
    console.error('❌ icon-list.txt not found');
    process.exit(1);
  }

  const names = fs
    .readFileSync(LIST_FILE, 'utf8')
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'));

  if (names.length === 0) {
    console.error('❌ icon-list.txt is empty');
    process.exit(1);
  }

  if (!fs.existsSync(OUTPUT_DIR)) {
    fs.mkdirSync(OUTPUT_DIR, { recursive: true });
  }

  let added = 0;
  let updated = 0;
  let skipped = 0;
  const missing = [];

  for (const rawName of names) {
    const id = normalizeName(rawName);
    const dest = path.join(OUTPUT_DIR, `${id}.svg`);

    const icon = findIconBySlug(id);

    if (!icon) {
      missing.push(rawName);
      continue;
    }

    const svg = buildColoredSvg(icon);

    // Skip if identical content already exists
    if (fs.existsSync(dest)) {
      const existingSvg = fs.readFileSync(dest, 'utf8');
      if (existingSvg === svg) {
        skipped++;
        continue;
      }
      fs.writeFileSync(dest, svg);
      updated++;
    } else {
      fs.writeFileSync(dest, svg);
      added++;
    }
  }

  console.log(`✅ Added: ${added}`);
  console.log(`🔄 Updated: ${updated}`);
  console.log(`⏭️  Skipped (no changes): ${skipped}`);

  if (missing.length > 0) {
    console.warn(`⚠️  Missing ${missing.length} icon(s):`);
    missing.forEach(name => console.warn(`   - ${name}`));
  }
}

main();
```

