const fs = require('fs');
const path = require('path');

const ICONS_DIR = path.join(__dirname, 'icons');
const CATEGORIES_FILE = path.join(__dirname, 'categories.json');
const OUTPUT_FILE = path.join(__dirname, 'ICONS.md');
const API_BASE = process.env.API_BASE || 'https://charmly.amrelmahdy001-b28.workers.dev';

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .replace(/\s+/g, '-');
}

function loadCategories() {
  if (!fs.existsSync(CATEGORIES_FILE)) return {};
  return JSON.parse(fs.readFileSync(CATEGORIES_FILE, 'utf8'));
}

function getExistingIcons() {
  if (!fs.existsSync(ICONS_DIR)) return [];
  return fs.readdirSync(ICONS_DIR)
    .filter(f => f.endsWith('.svg'))
    .map(f => f.replace('.svg', ''))
    .sort();
}

function generateTable(icons) {
  const ROWS = Math.ceil(icons.length / 3);
  const lines = [];
  lines.push('<table>');
  lines.push('  <tbody>');

  for (let row = 0; row < ROWS; row++) {
    lines.push('    <tr>');
    for (let col = 0; col < 3; col++) {
      const idx = row * 3 + col;
      const icon = icons[idx];
      if (icon) {
        lines.push(`      <td align="center"><code>${icon}</code></td>`);
        lines.push(`      <td align="center"><img src="${API_BASE}/icons?i=${icon}&perline=1" alt="${icon}" width="48" height="48"></td>`);
      } else {
        lines.push('      <td></td>');
        lines.push('      <td></td>');
      }
    }
    lines.push('    </tr>');
  }

  lines.push('  </tbody>');
  lines.push('</table>');
  return lines.join('\n');
}

function generateMarkdown() {
  const categories = loadCategories();
  const existing = new Set(getExistingIcons());

  const md = [];
  md.push('## Available Icons');
  md.push('');
  md.push(`Total icons: **${existing.size}**. Use the \`id\` shown next to each icon in your API call, e.g. \`?i=flutter,html,swift\`.`);
  md.push('');
  md.push('### Table of Contents');
  md.push('');

  const categorized = new Set();
  for (const [cat, icons] of Object.entries(categories)) {
    md.push(`- [${cat}](#${slugify(cat)})`);
    icons.forEach(i => categorized.add(i));
  }

  const uncategorized = [...existing].filter(i => !categorized.has(i));
  if (uncategorized.length > 0) {
    md.push('- [Uncategorized](#uncategorized)');
  }

  md.push('');

  // Generate each category
  for (const [cat, iconIds] of Object.entries(categories)) {
    const present = iconIds.filter(id => existing.has(id));
    if (present.length === 0) continue;

    md.push(`### ${cat}`);
    md.push('');
    md.push(generateTable(present));
    md.push('');
  }

  // Uncategorized
  if (uncategorized.length > 0) {
    md.push('### Uncategorized');
    md.push('');
    md.push(generateTable(uncategorized));
    md.push('');
  }

  return md.join('\n');
}

function main() {
  const markdown = generateMarkdown();
  fs.writeFileSync(OUTPUT_FILE, markdown);
  console.log(`✅ Generated ${OUTPUT_FILE}`);
}

main();
