```javascript
const fs = require('fs');
const path = require('path');

const ICONS_DIR = path.join(__dirname, 'icons');
const CATEGORIES_FILE = path.join(__dirname, 'categories.json');
const OUTPUT_FILE = path.join(__dirname, 'ICONS.md');

// API base URL — override via env var if needed
const API_BASE =
  process.env.API_BASE ||
  'https://charmly.amrelmahdy001-b28.workers.dev';

// ---------- Utilities ----------

function slugify(text) {
  return text
    .toLowerCase()
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/\s+/g, '-');
}

function loadCategories() {
  if (!fs.existsSync(CATEGORIES_FILE)) return {};
  try {
    return JSON.parse(fs.readFileSync(CATEGORIES_FILE, 'utf8'));
  } catch (err) {
    console.error('❌ Failed to parse categories.json:', err.message);
    return {};
  }
}

function getExistingIcons() {
  if (!fs.existsSync(ICONS_DIR)) return [];
  return fs
    .readdirSync(ICONS_DIR)
    .filter(f => f.endsWith('.svg'))
    .map(f => f.replace('.svg', ''))
    .sort();
}

// ---------- Table Generation ----------

/**
 * Generate an HTML table with 3 icons per row.
 * Columns per row: id, image, id, image, id, image (6 total).
 */
function generateTable(icons) {
  const ICONS_PER_ROW = 3;
  const rows = Math.ceil(icons.length / ICONS_PER_ROW);
  const lines = [];

  lines.push('<table>');
  lines.push('  <tbody>');

  for (let row = 0; row < rows; row++) {
    lines.push('    <tr>');

    for (let col = 0; col < ICONS_PER_ROW; col++) {
      const idx = row * ICONS_PER_ROW + col;
      const icon = icons[idx];

      if (icon) {
        const url = `${API_BASE}/icons?i=${icon}&perline=1`;
        lines.push(
          `      <td align="center"><code>${icon}</code></td>`
        );
        lines.push(
          `      <td align="center"><img src="${url}" alt="${icon}" width="48" height="48"></td>`
        );
      } else {
        lines.push('      <td></td>');
        lines.push('      <td></td>');
      }
    }

    lines.push('    </tr>');
  }

  lines.push('  </tbody>');
  lines.push('</table>');

  return lines.join('\n');
}

// ---------- Markdown Generation ----------

function generateMarkdown() {
  const categories = loadCategories();
  const existingIcons = getExistingIcons();
  const existingSet = new Set(existingIcons);

  if (existingIcons.length === 0) {
    console.error('❌ No icons found in icons/');
    process.exit(1);
  }

  const md = [];

  // Header
  md.push('## Available Icons');
  md.push('');
  md.push(
    `Total icons: **${existingIcons.length}**. Use the \`id\` shown next to each icon in your API call, e.g. \`?i=flutter,html,swift\`.`
  );
  md.push('');

  // Table of contents
  md.push('### Table of Contents');
  md.push('');

  const categorizedSet = new Set();

  for (const category of Object.keys(categories)) {
    md.push(`- [${category}](#${slugify(category)})`);
    for (const icon of categories[category]) categorizedSet.add(icon);
  }

  const uncategorized = existingIcons.filter(i => !categorizedSet.has(i));

  if (uncategorized.length > 0) {
    md.push('- [Uncategorized](#uncategorized)');
  }

  md.push('');

  // Category sections
  for (const [category, iconIds] of Object.entries(categories)) {
    const present = iconIds.filter(id => existingSet.has(id));

    if (present.length === 0) continue;

    md.push(`### ${category}`);
    md.push('');
    md.push(generateTable(present));
    md.push('');
  }

  // Uncategorized section
  if (uncategorized.length > 0) {
    md.push('### Uncategorized');
    md.push('');
    md.push(generateTable(uncategorized));
    md.push('');
  }

  return md.join('\n');
}

// ---------- Main ----------

function main() {
  const markdown = generateMarkdown();

  fs.writeFileSync(OUTPUT_FILE, markdown);

  const iconCount = getExistingIcons().length;
  const categoryCount = Object.keys(loadCategories()).length;

  console.log('');
  console.log('========================================');
  console.log('  Markdown Table Generated');
  console.log('========================================');
  console.log(`  Output:     ${path.basename(OUTPUT_FILE)}`);
  console.log(`  Icons:      ${iconCount}`);
  console.log(`  Categories: ${categoryCount}`);
  console.log('========================================');
  console.log('');
}

main();
