```javascript
function renderIcon(name, x, y, index, size, radius, bg, bgcolor, iconColor) {
  if (!hasIcon(name)) return '';
  const icon = icons[name];
  const clipId = `clip-${index}`;

  // Set `color` on the wrapper so that currentColor in icon paths
  // resolves to the user-chosen value. This makes icons without
  // explicit fill visible on both dark and light backgrounds.
  const innerSvg =
    `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" ` +
    `x="${PADDING}" y="${PADDING}" width="${size}" height="${size}" ` +
    `color="${iconColor}" ` +
    `viewBox="${icon.viewBox}" preserveAspectRatio="xMidYMid meet">${icon.content}</svg>`;

  if (!bg) {
    return `<g transform="translate(${x}, ${y})">${innerSvg}</g>`;
  }

  return `
    <g transform="translate(${x}, ${y})">
      <rect width="${size}" height="${size}" rx="${radius}" fill="${escapeAttr(bgcolor)}"/>
      <clipPath id="${clipId}">
        <rect width="${size}" height="${size}" rx="${radius}"/>
      </clipPath>
      <g clip-path="url(#${clipId})">${innerSvg}</g>
    </g>
  `;
}
```

