// Panel width (the text area on the right side of the image)
export const CARD_SIZES = {
  s: 250,
  m: 500,
  l: 750,
};

// Image width (the image on the left side)
export const IMAGE_WIDTHS = {
  s: 150,
  m: 250,
  l: 350,
  xl: 500,
};

export const CARD_CORNER_RADIUS = 12;
export const CARD_PADDING = 24;

export const DEFAULT_SIZE = 'm';
export const DEFAULT_IMAGE_SIZE = 'm';

// ---- Vertical baselines (relative to the card) ----
