```javascript
// ============================================================
// Card colors module.
// Parses and validates color parameters, produces gradients.
// ============================================================

import { validateHexColor } from '../utils.js';

export const DEFAULT_COLORS = ['#5865F2', '#1a1d2e'];

// Parses a colour param.
// Accepts:
//   null          → default pair
//   "hex"         → single color (duplicated as [c, c])
//   "hex1,hex2"   → two-color gradient
// Returns [from, to] or null on error.
export function parseColors(param) {
  if (param === null) return DEFAULT_COLORS.slice();

  const parts = param
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);

  if (parts.length === 0) return null;
  if (parts.length > 2) return null;

  const validated = parts.map((hex) => validateHexColor(hex));
  if (validated.some((v) => v === null)) return null;

  if (validated.length === 1) {
    return [validated[0], validated[0]];
  }
  return [validated[0], validated[1]];
}
