import { escapeXml, wrapText } from '../utils.js';
import { CARD_HEIGHT } from './layout.js';

// Description font sizes
export const DESC_SIZES = { s: 12, m: 14, l: 16 };
export const DEFAULT_DESC_SIZE = 'm';

// Title font size (fixed for now)
const TITLE_FONT_SIZE = 24;

// Default colors
