const DEFAULT_DESC_COLOR = '#a8b0c0';

export function validateDescSize(size) {
  if (size === null) return DEFAULT_DESC_SIZE;
  const lower = String(size).toLowerCase();
  if (!(lower in DESC_SIZES)) return null;
  return lower;
}

export function renderTitle({ title, color, x, baseline, maxWidth }) {
  const safeTitle = truncateToWidth(title, maxWidth, TITLE_FONT_SIZE);
  return `<text x="${x}" y="${baseline}" font-family="..." font-size="${TITLE_FONT_SIZE}" font-weight="700" fill="${escapeXml(color)}">${escapeXml(safeTitle)}</text>`;
}

export function renderTitleLine({ x, width, y, color }) {
  return `<line x1="${x}" y1="${y}" x2="${x + width}" y2="${y}" stroke="${escapeXml(color)}" stroke-width="1" stroke-opacity="0.3"/>`;
}

export function renderDescription({ desc, color, size, x, startY, maxWidth, lineHeight, maxLines }) {
  if (!desc || desc.trim() === '') return '';
  const fontSize = DESC_SIZES[size];
  // approximate chars per line based on font size
  const charsPerLine = Math.floor(maxWidth / (fontSize * 0.55));
  const lines = wrapText(desc, charsPerLine, maxLines);
  let out = '';
  lines.forEach((line, i) => {
    out += `<text x="${x}" y="${startY + i * lineHeight}" font-family="..." font-size="${fontSize}" fill="${escapeXml(color)}">${escapeXml(line)}</text>`;
  });
  return out;
}
