// ============================================================
// GitHub API client with caching.
// ============================================================

const CACHE_TTL_SECONDS = 3600; // 1 hour
const API_BASE = 'https://api.github.com';
const USER_AGENT = 'Charmly/1.0 (+https://github.com/amrelmahdy001/Charmly)';

// Parse "owner/repo" into { owner, repo } or null
export function parseRepoString(str) {
  if (!str) return null;
  const parts = str.split('/');
  if (parts.length !== 2) return null;
  const owner = parts[0].trim();
  const repo = parts[1].trim();
  if (!owner || !repo) return null;
  // Basic validation — GitHub owners and repos are alphanumeric + dashes/underscores/dots
  if (!/^[A-Za-z0-9._-]+$/.test(owner)) return null;
  if (!/^[A-Za-z0-9._-]+$/.test(repo)) return null;
  return { owner, repo };
}

// Fetch repo data with caching.
// Returns { stars, language } or null.
export async function fetchRepoData(owner, repo) {
  const cacheKey = new Request(
    `https://cache.internal/gh/repo/${owner}/${repo}`,
    { method: 'GET' }
  );
  const cache = caches.default;

  let cached = await cache.match(cacheKey);
  if (cached) {
    try {
      return await cached.json();
    } catch {
      // Bad cache — ignore
    }
  }

  try {
    const res = await fetch(`${API_BASE}/repos/${owner}/${repo}`, {
      headers: {
        'User-Agent': USER_AGENT,
        'Accept': 'application/vnd.github+json',
      },
    });
    if (!res.ok) return null;

    const data = await res.json();
    const result = {
      stars: typeof data.stargazers_count === 'number' ? data.stargazers_count : 0,
      language: typeof data.language === 'string' ? data.language : null,
    };

    // Store in cache
    const cacheResponse = new Response(JSON.stringify(result), {
      headers: {
        'Content-Type': 'application/json',
        'Cache-Control': `public, max-age=${CACHE_TTL_SECONDS}`,
      },
    });
    await cache.put(cacheKey, cacheResponse);

    return result;
  } catch {
    return null;
  }
}

// Fetch latest release tag with caching.
// Returns tag string or null.
export async function fetchLatestRelease(owner, repo) {
  const cacheKey = new Request(
    `https://cache.internal/gh/release/${owner}/${repo}`,
    { method: 'GET' }
  );
  const cache = caches.default;

  let cached = await cache.match(cacheKey);
  if (cached) {
    try {
      return await cached.text();
    } catch {
      // Bad cache
    }
  }

  try {
    const res = await fetch(`${API_BASE}/repos/${owner}/${repo}/releases/latest`, {
      headers: {
        'User-Agent': USER_AGENT,
        'Accept': 'application/vnd.github+json',
      },
    });
    if (!res.ok) return null;

    const data = await res.json();
    const tag = typeof data.tag_name === 'string' ? data.tag_name : null;

    if (tag) {
      const cacheResponse = new Response(tag, {
        headers: {
          'Content-Type': 'text/plain',
          'Cache-Control': `public, max-age=${CACHE_TTL_SECONDS}`,
        },
      });
      await cache.put(cacheKey, cacheResponse);
    }

    return tag;
  } catch {
    return null;
  }
}
