```javascript
// ============================================================
// GitHub API client with caching.
// Fetches repo data (stars, language) and latest release tag.
// Uses Cloudflare's Cache API to avoid hitting rate limits.
// ============================================================

const API_BASE = 'https://api.github.com';
const CACHE_TTL_SECONDS = 3600; // 1 hour
const USER_AGENT = 'Charmly/1.0 (+https://github.com/amrelmahdy001/Charmly)';

// ============================================================
// Public API
// ============================================================

// Fetches repo data with caching.
// Returns { stars, language } or null on failure.
export async function fetchRepoData(owner, repo) {
  const cacheKey = new Request(
    `https://cache.internal/gh/repo/${owner}/${repo}`,
    { method: 'GET' }
  );

  const cached = await safeCacheMatch(cacheKey);
  if (cached) {
    try {
      return await cached.json();
    } catch {
      // Corrupt cache entry — fall through to fetch
    }
  }

  try {
    const res = await fetch(`${API_BASE}/repos/${owner}/${repo}`, {
      headers: {
        'User-Agent': USER_AGENT,
        Accept: 'application/vnd.github+json',
      },
    });
    if (!res.ok) return null;

    const data = await res.json();
    const result = {
      stars:
        typeof data.stargazers_count === 'number' ? data.stargazers_count : 0,
      language: typeof data.language === 'string' ? data.language : null,
    };

    await safeCachePut(
      cacheKey,
      new Response(JSON.stringify(result), {
        headers: {
          'Content-Type': 'application/json',
          'Cache-Control': `public, max-age=${CACHE_TTL_SECONDS}`,
        },
      })
    );

    return result;
  } catch {
    return null;
  }
}

// Fetches latest release tag with caching.
// Returns tag string or null on failure.
export async function fetchLatestRelease(owner, repo) {
  const cacheKey = new Request(
    `https://cache.internal/gh/release/${owner}/${repo}`,
    { method: 'GET' }
  );

  const cached = await safeCacheMatch(cacheKey);
  if (cached) {
    try {
      return await cached.text();
    } catch {
      // Corrupt cache — fall through
    }
  }

  try {
    const res = await fetch(
      `${API_BASE}/repos/${owner}/${repo}/releases/latest`,
      {
        headers: {
          'User-Agent': USER_AGENT,
          Accept: 'application/vnd.github+json',
        },
      }
    );
    if (!res.ok) return null;

    const data = await res.json();
    const tag = typeof data.tag_name === 'string' ? data.tag_name : null;
    if (!tag) return null;

    await safeCachePut(
      cacheKey,
      new Response(tag, {
        headers: {
          'Content-Type': 'text/plain',
          'Cache-Control': `public, max-age=${CACHE_TTL_SECONDS}`,
        },
      })
    );

    return tag;
  } catch {
    return null;
  }
}

// ============================================================
// Internal: safe cache wrappers
// (Workers Cache API can throw in edge cases — never let it
//  break the card render.)
// ============================================================

async function safeCacheMatch(key) {
  try {
    return await caches.default.match(key);
  } catch {
    return null;
  }
}

async function safeCachePut(key, response) {
  try {
    await caches.default.put(key, response);
  } catch {
    // Ignore — cache is best-effort
  }
}
```

