## 📄 1️⃣ ملف جديد: `src/card/image-fetcher.js`

```javascript
// ============================================================
// Image fetcher for the card module.
// Downloads a remote image and converts it to a base64 data URI
// so it can be embedded directly inside the SVG.
//
// Why: GitHub's Content-Security-Policy blocks any <image> tag
// in an SVG that points to an external URL. The only way to
// render a remote image inside an SVG on GitHub is to inline
// it as a data URI.
// ============================================================

// Hard limit — anything larger risks the Worker CPU/memory budget
// and bloats the resulting SVG beyond what GitHub will render.
const MAX_IMAGE_BYTES = 200 * 1024; // 200 KB

// Only these MIME types are allowed.
const ALLOWED_TYPES = [
  'image/png',
  'image/jpeg',
  'image/jpg',
  'image/webp',
  'image/gif',
];

// ============================================================
// Public API
// ============================================================

// Fetches a remote image and returns it as a data URI.
//
// Returns:
//   "data:<mime>;base64,<...>"  on success
//   null                        on any failure
//
// Failure modes (all return null):
//   - invalid URL / non-http(s) scheme
//   - network error
//   - non-2xx response
//   - unexpected content-type
//   - oversized body
export async function fetchImageAsDataUri(imageUrl) {
  // ---- Validate URL ----
  let parsed;
  try {
    parsed = new URL(imageUrl);
  } catch {
    return null;
  }
  if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
    return null;
  }

  // ---- Fetch ----
  let res;
  try {
    res = await fetch(imageUrl, {
      headers: {
        'User-Agent': 'Charmly/1.0 (+https://github.com/amrelmahdy001/Charmly)',
        Accept: 'image/*',
      },
    });
  } catch {
    return null;
  }

  if (!res.ok) return null;

  // ---- Validate content-type ----
  const contentType = (res.headers.get('content-type') || '').toLowerCase();
  const mime = contentType.split(';')[0].trim();
  if (!ALLOWED_TYPES.includes(mime)) return null;

  // ---- Size check (via Content-Length first if available) ----
  const declaredLength = parseInt(res.headers.get('content-length') || '0', 10);
  if (declaredLength > MAX_IMAGE_BYTES) return null;

  // ---- Read body ----
  let buffer;
  try {
    buffer = await res.arrayBuffer();
  } catch {
    return null;
  }

  if (buffer.byteLength === 0) return null;
  if (buffer.byteLength > MAX_IMAGE_BYTES) return null;

  // ---- Convert to base64 ----
  // Use a chunked approach to avoid "Maximum call stack size exceeded"
  // when the image is large (spread operator / apply would blow up).
  const bytes = new Uint8Array(buffer);
  let binary = '';
  const CHUNK_SIZE = 8192;
  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
    const chunk = bytes.subarray(i, i + CHUNK_SIZE);
    binary += String.fromCharCode.apply(null, chunk);
  }

  let base64;
  try {
    base64 = btoa(binary);
  } catch {
    return null;
  }

  return `data:${mime};base64,${base64}`;
}
```

