const QRCode = (() => {
  // GF(256) tables
  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return EXP[LOG[a] + LOG[b]];
  }

  // Generator polynomial for RS
  function rsGenerator(n) {
    let poly = [1];
    for (let i = 0; i < n; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], EXP[i]);
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(data, nsym) {
    const gen = rsGenerator(nsym);
    const res = new Array(nsym).fill(0);
    for (const d of data) {
      const factor = d ^ res[0];
      res.shift();
      res.push(0);
      for (let i = 0; i < nsym; i++) {
        res[i] ^= gfMul(gen[i + 1], factor);
      }
    }
    return res;
  }

  // Version and EC tables (level H only)
  const EC_TABLE = {
    1: { ecPerBlock: 17, blocks: 1, total: 26 },
    2: { ecPerBlock: 28, blocks: 1, total: 44 },
    3: { ecPerBlock: 22, blocks: 2, total: 70 },
    4: { ecPerBlock: 16, blocks: 4, total: 100 },
    5: { ecPerBlock: 22, blocks: 4, total: 134 },
    6: { ecPerBlock: 28, blocks: 4, total: 172 },
    7: { ecPerBlock: 26, blocks: 5, total: 196 },
    8: { ecPerBlock: 26, blocks: 6, total: 242 },
    9: { ecPerBlock: 24, blocks: 8, total: 292 },
    10: { ecPerBlock: 28, blocks: 8, total: 346 },
    11: { ecPerBlock: 24, blocks: 11, total: 404 },
    12: { ecPerBlock: 28, blocks: 11, total: 466 },
    13: { ecPerBlock: 22, blocks: 16, total: 532 },
    14: { ecPerBlock: 24, blocks: 16, total: 581 },
    15: { ecPerBlock: 24, blocks: 18, total: 655 },
  };

  // Data capacity in bytes for byte mode
  function dataCapacity(version) {
    const t = EC_TABLE[version];
    const dataCodewords = t.total - t.blocks * t.ecPerBlock;
    // Overhead: 4 bits mode + length bits (8 for v1-9, 16 for v10+)
    const lengthBits = version <= 9 ? 8 : 16;
    const totalBits = dataCodewords * 8;
    return Math.floor((totalBits - 4 - lengthBits) / 8);
  }

  function chooseVersion(byteLen) {
    for (let v = 1; v <= 15; v++) {
      if (dataCapacity(v) >= byteLen) return v;
    }
    return -1;
  }

  // Alignment patterns per version
  const ALIGN = {
    1: [],
    2: [6, 18],
    3: [6, 22],
    4: [6, 26],
    5: [6, 30],
    6: [6, 34],
    7: [6, 22, 38],
    8: [6, 24, 42],
    9: [6, 26, 46],
    10: [6, 28, 50],
    11: [6, 30, 54],
    12: [6, 32, 58],
    13: [6, 34, 62],
    14: [6, 26, 46, 66],
    15: [6, 26, 48, 70],
  };

  function encode(text) {
    // Convert to UTF-8 bytes
    const bytes = [];
    for (const ch of text) {
      const code = ch.codePointAt(0);
      if (code < 0x80) {
        bytes.push(code);
      } else if (code < 0x800) {
        bytes.push(0xC0 | (code >> 6), 0x80 | (code & 0x3F));
      } else if (code < 0x10000) {
        bytes.push(0xE0 | (code >> 12), 0x80 | ((code >> 6) & 0x3F), 0x80 | (code & 0x3F));
      } else {
        bytes.push(0xF0 | (code >> 18), 0x80 | ((code >> 12) & 0x3F), 0x80 | ((code >> 6) & 0x3F), 0x80 | (code & 0x3F));
      }
    }

    const version = chooseVersion(bytes.length);
    if (version === -1) throw new Error('Data too long');

    const t = EC_TABLE[version];
    const dataCodewords = t.total - t.blocks * t.ecPerBlock;

    // Build bit stream: 4 bits mode (0100 = byte) + length + data
    const bits = [];
    function pushBits(val, len) {
      for (let i = len - 1; i >= 0; i--) {
        bits.push((val >> i) & 1);
      }
    }

    pushBits(4, 4); // byte mode
    const lengthBits = version <= 9 ? 8 : 16;
    pushBits(bytes.length, lengthBits);
