    const numBlocks = t.blocks;
    const ecPerBlock = t.ecPerBlock;
    const totalDataCodewords = dataBytes.length;
    const shortBlockSize = Math.floor(totalDataCodewords / numBlocks);
    const numLongBlocks = totalDataCodewords % numBlocks;
    const shortBlockDataLen = shortBlockSize;
    const longBlockDataLen = shortBlockSize + 1;

    const dataBlocks = [];
    const ecBlocks = [];
    let offset = 0;
    for (let i = 0; i < numBlocks; i++) {
      const blockLen = i < numBlocks - numLongBlocks ? shortBlockDataLen : longBlockDataLen;
      const block = dataBytes.slice(offset, offset + blockLen);
      offset += blockLen;
      dataBlocks.push(block);
      ecBlocks.push(rsEncode(block, ecPerBlock));
    }

    // Interleave data codewords
    const interleaved = [];
    const maxDataLen = longBlockDataLen;
    for (let i = 0; i < maxDataLen; i++) {
      for (const block of dataBlocks) {
        if (i < block.length) interleaved.push(block[i]);
      }
    }
    for (let i = 0; i < ecPerBlock; i++) {
      for (const block of ecBlocks) {
        interleaved.push(block[i]);
      }
    }

    // Build matrix
    const size = 17 + version * 4;
    const matrix = Array(size).fill(null).map(() => Array(size).fill(null));
    const reserved = Array(size).fill(null).map(() => Array(size).fill(false));

    // Finder patterns
    function placeFinder(row, col) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const rr = row + r;
          const cc = col + c;
          if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue;
          const isBlack = (
            (r >= 0 && r <= 6 && (c === 0 || c === 6)) ||
            (c >= 0 && c <= 6 && (r === 0 || r === 6)) ||
            (r >= 2 && r <= 4 && c >= 2 && c <= 4)
