function drawQR(ctx, matrix, px, color) {
  const total = matrix.length;
  const quiet = 4;
  const cellSize = px / (total + 2 * quiet);
  const offset = quiet * cellSize;

  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, px, px);

  // Helper: is this cell part of a finder pattern?
  function finderType(r, c) {
    // Top-left finder
    if (r <= 6 && c <= 6) return 'tl';
    // Top-right finder
    if (r <= 6 && c >= total - 7) return 'tr';
    // Bottom-left finder
    if (r >= total - 7 && c <= 6) return 'bl';
    return null;
  }

  // Helper: is this cell part of alignment pattern?
  // (skip for simplicity, treat as normal)

  ctx.fillStyle = color;

  // Draw all non-finder modules
  for (let r = 0; r < total; r++) {
    for (let c = 0; c < total; c++) {
      if (!matrix[r][c]) continue;
      if (finderType(r, c)) continue;
      const x = offset + c * cellSize;
      const y = offset + r * cellSize;
      drawRoundedSquare(ctx, x, y, cellSize, cellSize, cellSize * 0.4);
    }
  }

  // Draw finder patterns
  drawFinder(ctx, matrix, 0, 0, total, cellSize, offset);
  drawFinder(ctx, matrix, 0, total - 7, total, cellSize, offset);
  drawFinder(ctx, matrix, total - 7, 0, total, cellSize, offset);
}

function drawRoundedSquare(ctx, x, y, w, h, r) {
  if (ctx.roundRect) {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
    ctx.fill();
  } else {
    // Fallback
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    ctx.fill();
  }
}

function drawFinder(ctx, matrix, startRow, startCol, total, cellSize, offset) {
  const x = offset + startCol * cellSize;
  const y = offset + startRow * cellSize;
  const size = 7 * cellSize;

  // Outer rounded square (border)
  // Actually, the finder pattern is: 7x7 outer ring of black, 5x5 white, 3x3 black center
  // Draw as: filled rounded square 7x7, then white rounded square 5x5, then black rounded square 3x3

  const outerR = cellSize * 1.5;
  const innerR = cellSize * 1.1;
  const centerR = cellSize * 0.7;

  ctx.fillStyle = ctx.__color || '#000';

  // We'll use the current fillStyle which was set to color
  // Outer black rounded square
  drawRoundedSquare(ctx, x, y, size, size, outerR);

  // Inner white rounded square (5x5, offset by 1 cell)
  const innerX = x + cellSize;
  const innerY = y + cellSize;
  const innerSize = 5 * cellSize;
  ctx.fillStyle = '#FFFFFF';
  drawRoundedSquare(ctx, innerX, innerY, innerSize, innerSize, innerR);

  // Center black rounded square (3x3, offset by 2 cells)
  const centerX = x + 2 * cellSize;
  const centerY = y + 2 * cellSize;
  const centerSize = 3 * cellSize;
  ctx.fillStyle = ctx.__color || '#000';
  drawRoundedSquare(ctx, centerX, centerY, centerSize, centerSize, centerR);
}
