/* ============================================================
   QR CODE ENCODER (versions 1-10, level H, byte mode)
   Self-contained, no external dependencies
   ============================================================ */
const QREncoder = (() => {
  const EXP = new Uint8Array(512);
  const LOG = new Uint8Array(256);
  let x = 1;
  for (let i = 0; i < 255; i++) {
    EXP[i] = x;
    LOG[x] = i;
    x <<= 1;
    if (x & 0x100) x ^= 0x11d;
  }
  for (let i = 255; i < 512; i++) EXP[i] = EXP[i - 255];

  const gfMul = (a, b) => (a === 0 || b === 0) ? 0 : EXP[LOG[a] + LOG[b]];

  function rsGenerator(n) {
    let poly = [1];
    for (let i = 0; i < n; i++) {
      const next = new Array(poly.length + 1).fill(0);
      for (let j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], EXP[i]);
      }
      poly = next;
    }
    return poly;
  }

  function rsEncode(data, nsym) {
    const gen = rsGenerator(nsym);
    const res = new Array(nsym).fill(0);
    for (const d of data) {
      const factor = d ^ res[0];
      res.shift();
      res.push(0);
      for (let i = 0; i < nsym; i++) res[i] ^= gfMul(gen[i + 1], factor);
    }
    return res;
  }

  const EC_H = {
    1:  { ec: 17, blocks: 1, total: 26 },
    2:  { ec: 28, blocks: 1, total: 44 },
    3:  { ec: 22, blocks: 2, total: 70 },
    4:  { ec: 16, blocks: 4, total: 100 },
    5:  { ec: 22, blocks: 4, total: 134 },
    6:  { ec: 28, blocks: 4, total: 172 },
    7:  { ec: 26, blocks: 5, total: 196 },
    8:  { ec: 26, blocks: 6, total: 242 },
    9:  { ec: 24, blocks: 8, total: 292 },
    10: { ec: 28, blocks: 8, total: 346 },
  };

  const ALIGN = {
    1: [], 2: [6,18], 3: [6,22], 4: [6,26], 5: [6,30],
    6: [6,34], 7: [6,22,38], 8: [6,24,42], 9: [6,26,46], 10: [6,28,50],
  };

  const FORMAT_H = [
    0b001011010001001, 0b001001110111110, 0b001110011100111, 0b001100111010000,
    0b000011101100010, 0b000001001010101, 0b000110100001100, 0b000100000111011,
  ];

  const capacity = (v) => {
    const t = EC_H[v];
    const dataCw = t.total - t.blocks * t.ec;
    const lenBits = v <= 9 ? 8 : 16;
    return Math.floor((dataCw * 8 - 4 - lenBits) / 8);
  };

  const chooseVersion = (len) => {
    for (let v = 1; v <= 10; v++) if (capacity(v) >= len) return v;
    return -1;
  };

  function encode(text) {
    const bytes = [];
    for (const ch of text) {
      const cp = ch.codePointAt(0);
      if (cp < 0x80) bytes.push(cp);
      else if (cp < 0x800) bytes.push(0xC0 | (cp >> 6), 0x80 | (cp & 0x3F));
      else if (cp < 0x10000) bytes.push(0xE0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F));
      else bytes.push(0xF0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3F), 0x80 | ((cp >> 6) & 0x3F), 0x80 | (cp & 0x3F));
    }

    const version = chooseVersion(bytes.length);
    if (version === -1) throw new Error('Data too long (max ~119 bytes for version 10 H)');

    const t = EC_H[version];
    const dataCodewords = t.total - t.blocks * t.ec;
    const bits = [];
    const pushBits = (val, len) => { for (let i = len - 1; i >= 0; i--) bits.push((val >> i) & 1); };

    pushBits(4, 4);
    const lenBits = version <= 9 ? 8 : 16;
    pushBits(bytes.length, lenBits);
    for (const b of bytes) pushBits(b, 8);

    const totalDataBits = dataCodewords * 8;
    const term = Math.min(4, totalDataBits - bits.length);
    for (let i = 0; i < term; i++) bits.push(0);
    while (bits.length % 8 !== 0) bits.push(0);

    const pads = [0xEC, 0x11];
    let pi = 0;
    while (bits.length < totalDataBits) {
      pushBits(pads[pi % 2], 8);
      pi++;
    }

    const dataBytes = [];
    for (let i = 0; i < bits.length; i += 8) {
      let v = 0;
      for (let j = 0; j < 8; j++) v = (v << 1) | bits[i + j];
      dataBytes.push(v);
    }

    const numBlocks = t.blocks;
    const dataPerBlock = Math.floor(dataCodewords / numBlocks);
    const longBlocks = dataCodewords % numBlocks;
    const blocks = [];
    let off = 0;
    for (let i = 0; i < numBlocks; i++) {
      const isLong = i >= numBlocks - longBlocks;
      const len = dataPerBlock + (isLong ? 1 : 0);
      blocks.push(dataBytes.slice(off, off + len));
      off += len;
    }
    const ecBlocks = blocks.map(b => rsEncode(b, t.ec));

    const interleaved = [];
    const maxLen = Math.max(...blocks.map(b => b.length));
    for (let i = 0; i < maxLen; i++) {
      for (const b of blocks) if (i < b.length) interleaved.push(b[i]);
    }
    for (let i = 0; i < t.ec; i++) {
      for (const ec of ecBlocks) interleaved.push(ec[i]);
    }

    const size = 17 + version * 4;
    const matrix = Array(size).fill(null).map(() => new Array(size).fill(0));
    const reserved = Array(size).fill(null).map(() => new Array(size).fill(false));

    function placeFinder(r0, c0) {
      for (let r = -1; r <= 7; r++) {
        for (let c = -1; c <= 7; c++) {
          const rr = r0 + r, cc = c0 + c;
          if (rr < 0 || rr >= size || cc < 0 || cc >= size) continue;
          let val = 0;
          if (r >= 0 && r <= 6 && c >= 0 && c <= 6) {
            const outer = r === 0 || r === 6 || c === 0 || c === 6;
            const inner = r >= 2 && r <= 4 && c >= 2 && c <= 4;
            val = (outer || inner) ? 1 : 0;
          }
          matrix[rr][cc] = val;
          reserved[rr][cc] = true;
        }
      }
    }
    placeFinder(0, 0);
    placeFinder(0, size - 7);
    placeFinder(size - 7, 0);

    for (let i = 8; i < size - 8; i++) {
      matrix[6][i] = i % 2 === 0 ? 1 : 0; reserved[6][i] = true;
      matrix[i][6] = i % 2 === 0 ? 1 : 0; reserved[i][6] = true;
    }

    const alignPos = ALIGN[version];
    for (const ar of alignPos) {
      for (const ac of alignPos) {
        if ((ar === 6 && ac === 6) || (ar === 6 && ac === size - 7) || (ar === size - 7 && ac === 6)) continue;
        for (let r = -2; r <= 2; r++) {
          for (let c = -2; c <= 2; c++) {
            const isBorder = Math.abs(r) === 2 || Math.abs(c) === 2;
            const isCenter = r === 0 && c === 0;
            matrix[ar + r][ac + c] = (isBorder || isCenter) ? 1 : 0;
            reserved[ar + r][ac + c] = true;
          }
        }
      }
    }

    for (let i = 0; i < 9; i++) {
      if (!reserved[8][i]) reserved[8][i] = true;
      if (!reserved[i][8]) reserved[i][8] = true;
    }
    for (let i = 0; i < 8; i++) {
      reserved[8][size - 1 - i] = true;
      reserved[size - 1 - i][8] = true;
    }
    matrix[size - 8][8] = 1;
    reserved[size - 8][8] = true;

    const allBits = [];
    for (const b of interleaved) for (let i = 7; i >= 0; i--) allBits.push((b >> i) & 1);

    let bitIdx = 0, col = size - 1, up = true;
    while (col > 0) {
      if (col === 6) col--;
      const rows = up ? Array.from({length: size}, (_, i) => size - 1 - i) : Array.from({length: size}, (_, i) => i);
      for (const row of rows) {
        for (const c of [col, col - 1]) {
          if (c < 0 || reserved[row][c]) continue;
          matrix[row][c] = bitIdx < allBits.length ? allBits[bitIdx++] : 0;
        }
      }
      up = !up;
      col -= 2;
    }

    function applyMask(id) {
      const m = matrix.map(r => r.slice());
      for (let r = 0; r < size; r++) {
        for (let c = 0; c < size; c++) {
          if (reserved[r][c]) continue;
          let inv = false;
          switch (id) {
            case 0: inv = (r + c) % 2 === 0; break;
            case 1: inv = r % 2 === 0; break;
            case 2: inv = c % 3 === 0; break;
            case 3: inv = (r + c) % 3 === 0; break;
            case 4: inv = (Math.floor(r/2) + Math.floor(c/3)) % 2 === 0; break;
            case 5: inv = ((r*c) % 2) + ((r*c) % 3) === 0; break;
            case 6: inv = (((r*c) % 2) + ((r*c) % 3)) % 2 === 0; break;
            case 7: inv = (((r+c) % 2) + ((r*c) % 3)) % 2 === 0; break;
          }
          if (inv) m[r][c] ^= 1;
        }
      }
      return m;
    }

    function placeFormat(m, id) {
      const bits = FORMAT_H[id];
      for (let i = 0; i < 15; i++) {
        const bit = (bits >> i) & 1;
        if (i < 6) m[i][8] = bit;
        else if (i < 8) m[i + 1][8] = bit;
        else m[size - 15 + i][8] = bit;
        if (i < 8) m[8][size - 1 - i] = bit;
        else if (i === 8) m[8][7] = bit;
        else m[8][14 - i] = bit;
      }
      m[size - 8][8] = 1;
    }

    function penalty(m) {
      let s = 0;
      for (let r = 0; r < size; r++) {
        let run = 1;
        for (let c = 1; c < size; c++) {
          if (m[r][c] === m[r][c-1]) run++;
          else { if (run >= 5) s += 3 + (run - 5); run = 1; }
        }
        if (run >= 5) s += 3 + (run - 5);
      }
      for (let c = 0; c < size; c++) {
        let run = 1;
        for (let r = 1; r < size; r++) {
          if (m[r][c] === m[r-1][c]) run++;
          else { if (run >= 5) s += 3 + (run - 5); run = 1; }
        }
        if (run >= 5) s += 3 + (run - 5);
      }
      for (let r = 0; r < size - 1; r++)
        for (let c = 0; c < size - 1; c++)
          if (m[r][c] === m[r+1][c] && m[r][c] === m[r][c+1] && m[r][c] === m[r+1][c+1]) s += 3;
      let dark = 0;
      for (let r = 0; r < size; r++) for (let c = 0; c < size; c++) dark += m[r][c];
      s += Math.floor(Math.abs(dark * 100 / (size * size) - 50) / 5) * 10;
      return s;
    }

    let best = null, bestScore = Infinity;
    for (let id = 0; id < 8; id++) {
      const m = applyMask(id);
      placeFormat(m, id);
      const p = penalty(m);
      if (p < bestScore) { bestScore = p; best = m; }
    }

    return { matrix: best, size, version };
  }

  return { encode };
})();

