function drawRoundedRect(ctx, x, y, w, h, r) {
  if (typeof ctx.roundRect === 'function') {
    ctx.beginPath();
    ctx.roundRect(x, y, w, h, r);
  } else {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
}

function drawQRToCanvas(qrData, qrColor, logoImage, canvas) {
  const { matrix, size } = qrData;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#FFFFFF';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  const padding = 4;
  const cellSize = canvas.width / (size + padding * 2);
  const offset = padding * cellSize;
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;

  const logoSize = canvas.width * CONFIG.logoRatio;
  const exclusionRadius = logoSize * CONFIG.logoPaddingFactor;

  const alignCenters = [];
  const alignPos = ALIGN_CACHE[size] || [];
  for (const ar of alignPos) {
    for (const ac of alignPos) {
      if ((ar <= 7 && ac <= 7) || (ar <= 7 && ac >= size - 8) || (ar >= size - 8 && ac <= 7)) continue;
      alignCenters.push([ar, ac]);
    }
  }

  const isInFinder = (r, c) =>
    (r < 7 && c < 7) || (r < 7 && c >= size - 7) || (r >= size - 7 && c < 7);

  const isInAlignment = (r, c) =>
    alignCenters.some(([ar, ac]) => Math.abs(r - ar) <= 2 && Math.abs(c - ac) <= 2);

  ctx.fillStyle = qrColor;
  for (let r = 0; r < size; r++) {
    for (let c = 0; c < size; c++) {
      if (!matrix[r][c]) continue;
      if (isInFinder(r, c)) continue;
      if (isInAlignment(r, c)) continue;

      const x = offset + c * cellSize;
      const y = offset + r * cellSize;

      if (logoImage) {
        const mx = x + cellSize / 2, my = y + cellSize / 2;
        const dx = mx - cx, dy = my - cy;
        if (dx * dx + dy * dy < exclusionRadius * exclusionRadius) continue;
      }

      const inset = cellSize * 0.06;
      drawRoundedRect(ctx, x + inset, y + inset, cellSize - inset * 2, cellSize - inset * 2, cellSize * 0.35);
      ctx.fill();
    }
  }

  function drawFinder(r0, c0) {
    const x0 = offset + c0 * cellSize;
    const y0 = offset + r0 * cellSize;
    const outerSize = 7 * cellSize;

    ctx.fillStyle = qrColor;
    drawRoundedRect(ctx, x0, y0, outerSize, outerSize, outerSize * 0.22);
    ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    drawRoundedRect(ctx, x0 + cellSize, y0 + cellSize, 5 * cellSize, 5 * cellSize, 5 * cellSize * 0.22);
    ctx.fill();

    ctx.fillStyle = qrColor;
    drawRoundedRect(ctx, x0 + 2 * cellSize, y0 + 2 * cellSize, 3 * cellSize, 3 * cellSize, 3 * cellSize * 0.22);
    ctx.fill();
  }
  drawFinder(0, 0);
  drawFinder(0, size - 7);
  drawFinder(size - 7, 0);

  for (const [ar, ac] of alignCenters) {
    const x0 = offset + (ac - 2) * cellSize;
    const y0 = offset + (ar - 2) * cellSize;
    const outerSize = 5 * cellSize;

    ctx.fillStyle = qrColor;
    drawRoundedRect(ctx, x0, y0, outerSize, outerSize, outerSize * 0.22);
    ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    drawRoundedRect(ctx, x0 + cellSize, y0 + cellSize, 3 * cellSize, 3 * cellSize, 3 * cellSize * 0.22);
    ctx.fill();

    ctx.fillStyle = qrColor;
    drawRoundedRect(ctx, x0 + 2 * cellSize, y0 + 2 * cellSize, cellSize, cellSize, cellSize * 0.35);
    ctx.fill();
  }

  if (logoImage) {
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(cx, cy, exclusionRadius, 0, Math.PI * 2);
    ctx.fill();
    ctx.drawImage(logoImage, cx - logoSize / 2, cy - logoSize / 2, logoSize, logoSize);
  }
}

function wrapText(ctx, text, maxWidth, font, maxLines) {
  ctx.font = font;
  const words = text.split(/\s+/);
  const lines = [];
  let current = '';

  for (const word of words) {
    const test = current ? current + ' ' + word : word;
    if (ctx.measureText(test).width <= maxWidth) current = test;
    else {
      if (current) lines.push(current);
      current = word;
      if (lines.length === maxLines) break;
    }
  }
  if (current && lines.length < maxLines) lines.push(current);

  if (lines.length === maxLines) {
    const joined = lines.join(' ');
    const original = text.replace(/\s+/g, ' ').trim();
    if (joined !== original) {
      let last = lines[maxLines - 1];
      while (ctx.measureText(last + '…').width > maxWidth && last.length > 0) {
        last = last.slice(0, -1);
      }
      lines[maxLines - 1] = last + '…';
    }
  }
  return lines;
}

async function renderFinalCard(qrData, name, id, qrColor, textColor, logoImage) {
  const S = CONFIG.outputSize;
  const canvas = document.createElement('canvas');
  canvas.width = S;
  canvas.height = S;
  const ctx = canvas.getContext('2d');

  const inset = CONFIG.cardInset;
  ctx.fillStyle = '#FFFFFF';
  drawRoundedRect(ctx, inset, inset, S - inset * 2, S - inset * 2, CONFIG.cardRadius);
  ctx.fill();

  const qrCanvas = document.createElement('canvas');
  qrCanvas.width = 1000;
  qrCanvas.height = 1000;
  drawQRToCanvas(qrData, qrColor, logoImage, qrCanvas);

  const qrX = (S - CONFIG.qrSize) / 2;
  const qrY = inset + 15;
  ctx.drawImage(qrCanvas, qrX, qrY, CONFIG.qrSize, CONFIG.qrSize);

  await document.fonts.ready;

  const nameFont = `bold ${CONFIG.nameFontSize}px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif`;
  const idFont = `600 ${CONFIG.idFontSize}px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif`;

  const nameY = qrY + CONFIG.qrSize + 45;
  const lines = wrapText(ctx, name, S - inset * 2 - 40, nameFont, 2);

  ctx.fillStyle = textColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = nameFont;
  const lineHeight = CONFIG.nameFontSize + 8;
  lines.forEach((line, i) => ctx.fillText(line, S / 2, nameY + i * lineHeight));

  const idY = nameY + lines.length * lineHeight + 20;
  ctx.font = idFont;
  ctx.globalAlpha = 0.7;
  ctx.fillText(id, S / 2, idY);
  ctx.globalAlpha = 1;

  return canvas;
}

