async function renderFinalCard(qrData, name, id, qrColor, textColor, logoImage) {
  const W = CONFIG.outputWidth;
  const H = CONFIG.outputHeight;
  const canvas = document.createElement('canvas');
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext('2d');

  const inset = CONFIG.cardInset;
  ctx.fillStyle = '#FFFFFF';
  drawRoundedRect(ctx, inset, inset, W - inset * 2, H - inset * 2, CONFIG.cardRadius);
  ctx.fill();

  const qrCanvas = document.createElement('canvas');
  qrCanvas.width = 1000;
  qrCanvas.height = 1000;
  drawQRToCanvas(qrData, qrColor, logoImage, qrCanvas);

  const qrX = (W - CONFIG.qrSize) / 2;
  const qrY = inset + CONFIG.cardPaddingTop;
  ctx.drawImage(qrCanvas, qrX, qrY, CONFIG.qrSize, CONFIG.qrSize);

  await document.fonts.ready;

  const nameFont = `bold ${CONFIG.nameFontSize}px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif`;
  const idFont = `600 ${CONFIG.idFontSize}px system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif`;

  const nameY = qrY + CONFIG.qrSize + CONFIG.gapQRName;
  const lines = wrapText(ctx, name, W - inset * 2 - 40, nameFont, 2);

  ctx.fillStyle = textColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.font = nameFont;
  const lineHeight = CONFIG.nameFontSize + 8;
  lines.forEach((line, i) => ctx.fillText(line, W / 2, nameY + i * lineHeight));

  const idY = nameY + lines.length * lineHeight + CONFIG.gapNameID;
  ctx.font = idFont;
  ctx.globalAlpha = 0.7;
  ctx.fillText(id, W / 2, idY);
  ctx.globalAlpha = 1;

  return canvas;
}
