## 4️⃣ استبدل دالة `doRender` كاملة

دوّر على `async function doRender` واستبدلها بالدالة دي:

```js
async function doRender() {
  const url = state.url.trim();
  const name = state.name.trim();
  const id = state.id.trim().toUpperCase();

  const urlValid = url.length === 0 || isValidUrl(url);
  document.getElementById('urlError').classList.toggle('show', url.length > 0 && !urlValid);

  const valid = url.length > 0 && name.length > 0 && id.length > 0 && urlValid;
  downloadBtn.disabled = !valid;

  if (!valid) {
    const W = CONFIG.outputWidth, H = CONFIG.outputHeight;
    previewCanvas.width = W;
    previewCanvas.height = H;
    const ctx = previewCanvas.getContext('2d');
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#FFFFFF';
    drawRoundedRect(ctx, CONFIG.cardInset, CONFIG.cardInset, W - CONFIG.cardInset * 2, H - CONFIG.cardInset * 2, CONFIG.cardRadius);
    ctx.fill();
    ctx.fillStyle = '#ccc';
    ctx.font = 'bold 22px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Fill in the fields to see preview', W / 2, H / 2);
    return;
  }

  let processedUrl = url;
  if (!/^https?:\/\//i.test(processedUrl)) processedUrl = 'https://' + processedUrl;

  try {
    const qrData = QREncoder.encode(processedUrl);
    const final = await renderFinalCard(qrData, name, id, state.qrColor, state.textColor, state.logoImage);
    previewCanvas.width = final.width;
    previewCanvas.height = final.height;
    const ctx = previewCanvas.getContext('2d');
    ctx.clearRect(0, 0, final.width, final.height);
    ctx.drawImage(final, 0, 0);
  } catch (err) {
    const W = CONFIG.outputWidth, H = CONFIG.outputHeight;
    previewCanvas.width = W;
    previewCanvas.height = H;
    const ctx = previewCanvas.getContext('2d');
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#FFFFFF';
    drawRoundedRect(ctx, CONFIG.cardInset, CONFIG.cardInset, W - CONFIG.cardInset * 2, H - CONFIG.cardInset * 2, CONFIG.cardRadius);
    ctx.fill();
    ctx.fillStyle = '#c33';
    ctx.font = 'bold 18px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(err.message, W / 2, H / 2);
  }
}
```

